control.patch:
diff --git a/include/fmt/chrono.h b/include/fmt/chrono.h
index c0b88b3..f94a9a8 100644
--- a/include/fmt/chrono.h
+++ b/include/fmt/chrono.h
@@ -1686,11 +1686,8 @@ struct duration_formatter {
       write_nan();
       return true;
     }
-    // must be +-inf
-    if (val > 0)
-      std::copy_n("inf", 3, out);
-    else
-      std::copy_n("-inf", 4, out);
+    write_sign();
+    std::copy_n("inf", 3, out);
     return true;
   }

@@ -1815,7 +1812,7 @@ struct duration_formatter {
         auto buf = memory_buffer();
         write_floating_seconds(buf, std::chrono::duration<rep, Period>(val),
                                precision);
-        if (negative) *out++ = '-';
+        write_sign();
         if (buf.size() < 2 || buf[1] == '.')
           out = detail::write_padding(out, pad);
         out = copy<Char>(buf.begin(), buf.end(), out);
diff --git a/test/chrono-test.cc b/test/chrono-test.cc
index a2f419a..fe8e475 100644
--- a/test/chrono-test.cc
+++ b/test/chrono-test.cc
@@ -755,6 +755,43 @@ TEST(chrono_test, special_durations) {
       "01.234");
 }

+TEST(chrono_test, floating_duration_sign) {
+  auto d = std::chrono::duration<double>(-61.25);
+  EXPECT_EQ(fmt::format("{:%S %S}", d), "-01.250000 01.250000");
+  EXPECT_EQ(fmt::format("{:%S %Q}", d), "-01.250000 61.25");
+  EXPECT_EQ(fmt::format("{:%Q %S}", d), "-61.25 01.250000");
+  EXPECT_EQ(fmt::format("{:%S %M}", d), "-01.250000 01");
+  EXPECT_EQ(fmt::format("{:%T %T}", d),
+            "-00:01:01.250000 00:01:01.250000");
+  EXPECT_EQ(fmt::format("{:%S %R %T}", d),
+            "-01.250000 00:01 00:01:01.250000");
+  EXPECT_EQ(fmt::format("{:.2%S %Q}", d), "-01.25 61.25");
+  EXPECT_EQ(fmt::format("{:%S %Q}", std::chrono::duration<float>(-61.25)),
+            "-01.250000 61.25");
+  EXPECT_EQ(fmt::format("{:%S %Q}", dms(-1250)), "-01.250 1250");
+  EXPECT_EQ(fmt::format("{:%S %Q %T}", -d),
+            "01.250000 61.25 00:01:01.250000");
+  EXPECT_EQ(fmt::format("{:%S %Q %T}", std::chrono::seconds(-61)),
+            "-01 61 00:01:01");
+  EXPECT_EQ(fmt::format("{:%S %Q %T}", std::chrono::seconds(61)),
+            "01 61 00:01:01");
+}
+
+TEST(chrono_test, infinite_duration_sign) {
+  auto inf = std::chrono::duration<double>(
+      std::numeric_limits<double>::infinity());
+  EXPECT_EQ(fmt::format("{:%S}", -inf), "-inf");
+  EXPECT_EQ(fmt::format("{:%Q}", -inf), "-inf");
+  EXPECT_EQ(fmt::format("{:%R}", -inf), "-inf:inf");
+  EXPECT_EQ(fmt::format("{:%T}", -inf), "-inf:inf:inf");
+  EXPECT_EQ(fmt::format("{:%S %Q %R %T}", -inf),
+            "-inf inf inf:inf inf:inf:inf");
+  EXPECT_EQ(fmt::format("{:%Q %S}", -inf), "-inf inf");
+  EXPECT_EQ(fmt::format("{:%R %S}", -inf), "-inf:inf inf");
+  EXPECT_EQ(fmt::format("{:%S %Q %R %T}", inf),
+            "inf inf inf:inf inf:inf:inf");
+}
+
 TEST(chrono_test, unsigned_duration) {
   EXPECT_EQ(fmt::format("{}", std::chrono::duration<unsigned>(42)), "42s");
 }

